import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{public static void main(String[] a)throws Exception{Map<String,byte[]> data=new TreeMap<>();int population=0,horde=0,methods=0;try(ZipFile z=new ZipFile(a[0])){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();byte[] b=z.getInputStream(e).readAllBytes();if(Set.of("dev/zomboid/danger/Zones.class","dev/zomboid/hordes/HordeRules.class").contains(e.getName())){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods){if(c.name.endsWith("/Zones")&&m.name.equals("missing")){for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.name.equals("multiplier")){AbstractInsnNode multiply=n.getNext();while(multiply!=null&&multiply.getOpcode()<0)multiply=multiply.getNext();if(multiply==null||multiply.getOpcode()!=IMUL)throw new IllegalStateException("target multiply missing");m.instructions.insert(multiply,new MethodInsnNode(INVOKESTATIC,"dev/zomboid/hordes/Population35","scale","(I)I",false));population++;}}if(c.name.endsWith("/HordeRules")&&m.name.equals("budget"))for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==IRETURN){m.instructions.insertBefore(n,new MethodInsnNode(INVOKESTATIC,"dev/zomboid/hordes/Population35","scale","(I)I",false));horde++;}}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}data.put(e.getName(),b);}}
if(population!=1||horde!=1)throw new IllegalStateException("Population/budget hooks: "+population+","+horde);try(var f=Files.walk(Path.of(a[2]))){for(var p:f.filter(p->p.toString().endsWith(".class")).toList())data.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}for(var e:data.entrySet())if(e.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(e.getValue()).accept(c,0);for(var m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0){new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);methods++;}}try(var z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}System.out.println("Population and horde quantity hooks matched; verified methods "+methods);
try(var old=new java.net.URLClassLoader(new java.net.URL[]{Path.of(a[0]).toUri().toURL()},ClassLoader.getPlatformClassLoader());var fresh=new java.net.URLClassLoader(new java.net.URL[]{Path.of(a[1]).toUri().toURL()},ClassLoader.getPlatformClassLoader())){var before=old.loadClass("dev.zomboid.hordes.HordeRules").getMethod("budget",int.class,int.class,int.class,int.class);var after=fresh.loadClass("dev.zomboid.hordes.HordeRules").getMethod("budget",int.class,int.class,int.class,int.class);for(int n:new int[]{0,1,20,100})for(int players:new int[]{1,2,4}){int x=(Integer)before.invoke(null,n,players,10,200),y=(Integer)after.invoke(null,n,players,10,200);if(y!=Math.round(x*.65))throw new IllegalStateException("Native budget mismatch");}System.out.println("12 original/patched native budget comparisons passed");}}
}
